package cli

import (
	"fmt"
	"strings"
	"time"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

func newWatchAddCmd(flags *rootFlags) *cobra.Command {
	var flagThreshold float64

	cmd := &cobra.Command{
		Use:   "add <product-url>",
		Short: "Add a Flipkart product to your local price watchlist.",
		Long:  "Records a product URL and a price threshold locally. Use `watch check` to re-fetch current prices and `watch digest` to see what changed.",
		Example: strings.Trim(`
  flipkart-pp-cli watch add "https://www.flipkart.com/oppo-a3x-8-gb-ram-128-gb-storage-lake-green/p/itmc050065f36601?pid=MOBH4ZCFEQZFQBFB" --threshold 15999
`, "\n"),
		// Not annotated mcp:read-only: unlike the other commands in this
		// build, this one persists new local state (a new watch row) rather
		// than only reading/observing, so it's left classified as a write.
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			productURL := args[0]

			// dry-run must short-circuit before the required-flag check
			// so `--dry-run` always succeeds (per the Verify-friendly
			// RunE convention) regardless of whether --threshold is set.
			// pid resolution is still attempted for a richer preview, but
			// its failure doesn't block the dry-run response — a synthetic
			// probe URL with no ?pid=... shouldn't turn a dry-run into an
			// error.
			if dryRunOK(flags) {
				thresholdMsg := "(not set)"
				if cmd.Flags().Changed("threshold") {
					thresholdMsg = fmt.Sprintf("%v", flagThreshold)
				}
				pid, pidErr := pidFromURL(productURL)
				if pidErr != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "would add watch: url %s at threshold %s (could not resolve product id from URL: %v)\n(dry run - no data written)\n", productURL, thresholdMsg, pidErr)
					return nil
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "would add watch: product %s at threshold %s (url: %s)\n(dry run - no data written)\n", pid, thresholdMsg, productURL)
				return nil
			}

			if !cmd.Flags().Changed("threshold") {
				return usageErr(fmt.Errorf("--threshold is required\nUsage: %s <product-url> --threshold <price>", cmd.CommandPath()))
			}
			if flagThreshold <= 0 {
				return usageErr(fmt.Errorf("--threshold must be a positive number, got %v", flagThreshold))
			}

			pid, err := pidFromURL(productURL)
			if err != nil {
				return usageErr(err)
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			now := time.Now()
			if err := db.UpsertFlipkartWatch(pid, productURL, flagThreshold, now); err != nil {
				return fmt.Errorf("saving watch: %w", err)
			}

			return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
				"product_id": pid,
				"url":        productURL,
				"threshold":  flagThreshold,
				"added_at":   now.UTC().Format(time.RFC3339),
			}, flags)
		},
	}
	cmd.Flags().Float64Var(&flagThreshold, "threshold", 0, "Alert threshold price (required)")
	return cmd
}
